import {checks,crew,findings,reviewIsCurrent} from './core.mjs';
import {esc} from './customer-shared.mjs';
import {proofIsCurrent} from './operations.mjs';

const prompts=[
 {agent:0,text:'Which payment fields match this purchase?'},
 {agent:1,text:'What does the event trail actually prove?'},
 {agent:2,text:'What exactly would the smallest repair change?'},
 {agent:3,text:'What concern could still block this repair?'}
];
const pending=new Map();

export function agentEvidencePanel(s){
 if(!s?.review)return '';
 const entries=s.analysis?.mode==='model'&&Array.isArray(s.analysis.findings)?s.analysis.findings:findings(s);
 const snapshot=s.review.snapshot||{};
 const cards=entries.map(item=>`<article class="agent-evidence-card"><div class="agent-evidence-person"><span class="specialist-avatar specialist-${item.agent}">${esc(crew[item.agent]?.name?.slice(0,1)||'?')}</span><div><strong>${esc(crew[item.agent]?.name||'Specialist')}</strong><small>${esc(crew[item.agent]?.role||'Case analyst')}</small></div></div><p>${esc(item.summary)}</p><div class="agent-evidence-foot"><span>${esc(item.unknown||'The records do not establish every cause.')}</span><details><summary>Inspect ${item.sources?.length||0} source${item.sources?.length===1?'':'s'}</summary>${(item.sources||[]).map(source=>`<div><strong>${esc(source)}</strong><pre>${esc(JSON.stringify(snapshot[source]??null,null,2))}</pre></div>`).join('')}</details></div></article>`).join('');
 const objections=(s.review.objections||[]).filter(item=>item.id?.startsWith('model-'));
 return `<section class="agent-evidence-panel" aria-label="Four specialist findings"><div class="agent-evidence-title"><span class="eyebrow">THE FOUR PERSPECTIVES</span><h3>What each specialist found</h3><p>Open a source to inspect the record used in this saved review. A citation identifies a record; it does not prove every claim in a summary.</p></div><div class="agent-evidence-grid">${cards}</div>${objections.length?`<div class="agent-objection-list"><h4>Prism’s safety questions</h4>${objections.map(item=>`<div class="agent-objection ${esc(item.status)}"><strong>${esc(item.status==='resolved'?'Answered':'Needs evidence')}</strong><p>${esc(item.question)}</p><small>${esc(item.resolution||'No answer recorded.')} · Sources: ${esc((item.resolutionSources||item.sources||[]).join(', '))}</small></div>`).join('')}</div>`:''}</section>`;
}

export function agentBrief(s){
 const r=s?.review,current=!!r&&reviewIsCurrent(s);
 if(!r)return {tone:'waiting',title:'A decision needs current evidence.',next:'Run the investigation to collect four perspectives.',confirmed:[],open:[],unknown:'No specialist conclusion has been recorded.'};
 if(s.writes)return {tone:proofIsCurrent(s)?'ready':'needs-evidence',title:proofIsCurrent(s)?'The access outcome was verified.':'The approved access change needs verification.',next:proofIsCurrent(s)?'Ask the customer to open the purchase and confirm their experience.':'Check the payment, entitlement, and protected lesson again. Do not repeat the grant.',confirmed:[],open:[],unknown:'The original agent recommendation is archived; the outcome depends on fresh checks.'};
 if(!current)return {tone:'stale',title:'This review belongs to older evidence.',next:'Investigate the changed records before considering a correction.',confirmed:[],open:[],unknown:'The earlier recommendation cannot authorize a new change.'};
 const checked=checks(s),confirmed=checked.filter(item=>item.ok).map(item=>item.label),failed=checked.filter(item=>!item.ok).map(item=>item.label);
 const open=r.objections.filter(item=>item.status==='open').map(item=>item.question);
 const titles={ready:'Evidence supports a preview.',blocked:'The proposed repair is blocked.','needs-evidence':'The team needs more evidence.','verify-only':'Access may already be present.'};
 const next={ready:'Preview the exact grant, then decide whether to approve it.',blocked:'Resolve the failed purchase checks; do not grant access.','needs-evidence':'Answer the open objections and run a fresh investigation.','verify-only':'Verify the existing access without another grant.'};
 return {tone:r.outcome,title:titles[r.outcome]||'Review the evidence.',next:next[r.outcome]||'Inspect the case before changing access.',confirmed,open:[...failed.map(label=>'Failed check: '+label),...open],unknown:r.unknown};
}

export function mountAgentWorkbench(root,s,{backend=false,ai=false,operator=false,busy=false,api,onUpdate}={}){
 if(!s)return;const target=root.querySelector('.case-evidence-column');if(!target)return;
 const brief=agentBrief(s),current=!!s.review&&reviewIsCurrent(s),currentQuestions=(s.agentQuestions||[]).filter(item=>item.reviewFingerprint===s.review?.fingerprint);
 const enabled=backend&&ai&&operator&&current&&s.review.mode==='model'&&!s.job?.pending&&!busy&&currentQuestions.length<8;
 const reason=!backend?'This browser preview uses scripted sample records.':!ai?'Configure an AI model on the server to ask a specialist.':!operator?'Unlock the operator session to ask a specialist.':!current?'Run a current investigation first.':s.review.mode!=='model'?'Run a model-backed investigation first.':s.job?.pending?'Wait for the current workflow to finish.':currentQuestions.length>=8?'This review has reached its eight-question limit.':'';
 const panel=document.createElement('section');panel.className='agent-workbench';panel.setAttribute('aria-label','Agent decision desk');
 const draft=pending.get(s.id);
 panel.innerHTML=`<div class="agent-workbench-head"><div><span class="eyebrow">AGENT DECISION DESK</span><h2>Understand the recommendation.</h2><p>A readable brief, source-backed follow-ups, and the merchant’s next controlled step.</p></div><span class="agent-workbench-mode">${s.review?.mode==='model'?(s.analysis?.provider==='azure-openai'?'Azure AI review':'AI review'):s.review?'Scripted demo':'Awaiting review'}</span></div><div class="agent-brief ${esc(brief.tone)}"><div class="agent-brief-main"><span class="eyebrow">THE DECISION</span><h3>${esc(brief.title)}</h3><p>${esc(brief.next)}</p></div><div class="agent-brief-columns"><div><strong>Confirmed by case checks</strong>${brief.confirmed.length?`<ul>${brief.confirmed.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p>No current checks can support a correction yet.</p>'}</div><div><strong>Still open</strong>${brief.open.length?`<ul>${brief.open.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:`<p>${esc(brief.unknown)}</p>`}</div></div><small>Specialists explain. Only the merchant approves. A separate access check verifies the result.</small></div><div class="agent-ask"><div><span class="eyebrow">ASK A SPECIALIST</span><h3>One question. One cited answer.</h3><p>Questions are read-only and use the saved review snapshot. Answers cannot approve or apply a repair.</p></div><div class="agent-question-starters">${prompts.map((item,i)=>`<button type="button" data-starter="${i}" ${enabled?'':'disabled'}>${esc(crew[item.agent].name)} · ${esc(item.text)}</button>`).join('')}</div><form class="agent-question-form"><label for="agent-choice">Specialist</label><select id="agent-choice" ${enabled?'':'disabled'}>${crew.map((member,i)=>`<option value="${i}" ${Number(draft?.agent)===i?'selected':''}>${esc(member.name)} · ${esc(member.role)}</option>`).join('')}</select><label for="agent-question">Your question</label><textarea id="agent-question" required maxlength="400" placeholder="Ask about this purchase’s evidence or the proposed correction." ${enabled?'':'disabled'}>${esc(draft?.question||'')}</textarea><div class="agent-question-actions"><button class="button primary" type="submit" ${enabled?'':'disabled'}>Ask specialist</button><small>${enabled?`${8-currentQuestions.length} questions left for this review.`:esc(reason)}</small></div></form><p class="agent-question-feedback" role="status"></p></div><div class="agent-answer-history"><span class="eyebrow">SAVED FOLLOW-UPS</span><h3>Questions and cited answers</h3>${(s.agentQuestions||[]).length?`<div class="agent-answer-list">${[...s.agentQuestions].reverse().map(item=>`<article class="agent-answer"><div><strong>${esc(crew[item.agent]?.name||'Specialist')}</strong><span>${item.reviewFingerprint===s.review?.fingerprint?'Current review':'Earlier review'} · ${esc(new Date(item.at).toLocaleString())}</span></div><h4>${esc(item.question)}</h4><p>${esc(item.answer)}</p><p class="agent-answer-unknown"><strong>Still uncertain:</strong> ${esc(item.unknown)}</p><details><summary>Inspect cited records · ${(item.sources||[]).length}</summary>${(item.sources||[]).map(source=>`<div><strong>${esc(source)}</strong><pre>${esc(JSON.stringify(item.citedSnapshot?.[source]??null,null,2))}</pre></div>`).join('')}</details></article>`).join('')}</div>`:'<p>No follow-up questions have been asked for this case.</p>'}</div>`;
 const anchor=target.querySelector('.breakpoint-map')||target.querySelector('.clarity-specialists');if(anchor)anchor.after(panel);else target.append(panel);
 panel.querySelectorAll('[data-starter]').forEach(button=>button.onclick=()=>{const starter=prompts[Number(button.dataset.starter)];panel.querySelector('#agent-choice').value=String(starter.agent);panel.querySelector('#agent-question').value=starter.text;panel.querySelector('#agent-question').focus();});
 panel.querySelector('.agent-question-form').onsubmit=async event=>{event.preventDefault();if(!enabled)return;const agent=Number(panel.querySelector('#agent-choice').value),question=panel.querySelector('#agent-question').value.trim(),feedback=panel.querySelector('.agent-question-feedback');if(!question)return;let request=pending.get(s.id);if(!request||request.agent!==agent||request.question!==question)request={agent,question,requestId:crypto.randomUUID()};pending.set(s.id,request);panel.querySelectorAll('button,select,textarea').forEach(control=>control.disabled=true);feedback.textContent=`Asking ${crew[agent].name} about the reviewed evidence…`;try{const result=await api('agent/question',{caseId:s.id,...request},{requestTimeoutMs:70000});pending.delete(s.id);onUpdate?.(result.state);}catch(error){if(error.code==='rejected')pending.delete(s.id);feedback.textContent=error.message+' No access change was requested.';panel.querySelectorAll('button,select,textarea').forEach(control=>control.disabled=false);}};
}
